def apply(inputs, premises):
    personal_used = False
    carry_used = False
    checked = []
    n = len(inputs["item_lengths"])
    for i in range(n):
        personal_ok = float(inputs["item_lengths"][i]) <= float(premises["personal_item_limits"][0]) and float(inputs["item_widths"][i]) <= float(premises["personal_item_limits"][1]) and float(inputs["item_heights"][i]) <= float(premises["personal_item_limits"][2])
        carry_ok = float(inputs["item_lengths"][i]) <= float(premises["carry_on_limits"][0]) and float(inputs["item_widths"][i]) <= float(premises["carry_on_limits"][1]) and float(inputs["item_heights"][i]) <= float(premises["carry_on_limits"][2])
        if personal_ok and not personal_used:
            personal_used = True
        elif carry_ok and not carry_used:
            carry_used = True
        else:
            checked = checked + [i]
    total = int(inputs["ticket_price"])
    for j in range(len(checked)):
        i = checked[j]
        if j == 0:
            base = int(inputs["first_checked_bag_fee"])
        elif j == 1:
            base = int(inputs["second_checked_bag_fee"])
        elif j == 2:
            base = int(inputs["third_checked_bag_fee"])
        else:
            base = int(inputs["fourth_and_later_checked_bag_fee"])
        weight = float(inputs["item_weights"][i])
        overweight = 0
        if weight > float(inputs["standard_checked_weight_limit"]):
            if weight <= float(premises["weight_band_upper_limits"][0]):
                overweight = int(inputs["overweight_fee_first_band"])
            elif weight <= float(premises["weight_band_upper_limits"][1]):
                overweight = int(inputs["overweight_fee_second_band"])
            else:
                overweight = int(inputs["overweight_fee_third_band"])
        size = float(inputs["item_lengths"][i]) + float(inputs["item_widths"][i]) + float(inputs["item_heights"][i])
        oversize = 0
        if size > float(premises["size_band_boundaries"][0]):
            if size <= float(premises["size_band_boundaries"][1]):
                oversize = int(inputs["oversize_fee_first_band"])
            else:
                oversize = int(inputs["oversize_fee_second_band"])
        excess = max(overweight, oversize)
        total = total + base + excess
    return {"answer": total}

